const toggle=document.getElementById('menu-toggle'),side=document.getElementById('sidebar');toggle?.addEventListener('click',()=>{const open=side.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open))});document.addEventListener('keydown',e=>{if(e.key==='Escape'){side.classList.remove('open');toggle?.setAttribute('aria-expanded','false')}});const input=document.getElementById('search'),select=document.getElementById('status-filter'),cards=[...document.querySelectorAll('article.card')];const norm=s=>s.replace(/œ/g,'oe').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();function filter(){let count=0;const q=norm(input?.value||''),st=select?.value||'all';cards.forEach(card=>{const status=card.querySelector('.status');const visible=norm(card.textContent).includes(q)&&(st==='all'||status.classList.contains(st));card.hidden=!visible;if(visible)count++});document.getElementById('results').textContent=count+' '+(document.documentElement.lang==='en'?(count===1?'project':'projects'):(count===1?'projet':'projets'));let empty=document.getElementById('empty-message');if(!empty){empty=document.createElement('p');empty.id='empty-message';empty.className='empty';document.getElementById('grid').appendChild(empty)}empty.textContent=document.documentElement.lang==='en'?'No projects found. Try another word or remove the filter.':'Aucun projet trouvé. Essayez un autre mot ou retirez le filtre.';empty.hidden=count!==0}input?.addEventListener('input',filter);select?.addEventListener('change',filter);
